import * as React from "react";
import styles from "./LicenseMatrixView.module.scss";
import { LicenseAllocationService, ILicenseAllocation } from "../../services/LicenseAllocationService";

interface IProps {
serviceContext:any;
onClientSelect?:(client:string)=>void;
onBack?:()=>void;
}

interface IState {
loading:boolean;
allocations:ILicenseAllocation[];
clients:string[];
licenses:string[];
error?:string;
}

export default class LicenseMatrixView extends React.Component<IProps,IState>{

private service:LicenseAllocationService;

constructor(props:IProps){
super(props);
this.service=new LicenseAllocationService(props.serviceContext);
this.state={loading:true,allocations:[],clients:[],licenses:[]};
}

public async componentDidMount(){
await this.loadData();
}

private async loadData(){

try{

const data=await this.service.getAllocations();

const clients=Array.from(new Set(
data.map(x=>x.ITRequest?.Client?.Title).filter(Boolean)
)) as string[];

const licenses=Array.from(new Set(
data.map(x=>x.License?.Title).filter(Boolean)
)) as string[];

this.setState({
allocations:data,
clients,
licenses,
loading:false
});

}
catch(error){

this.setState({
loading:false,
error:"Unable to load license allocations"
});

}

}

private getCount(client:string,license:string){

return this.state.allocations.filter(x=>
x.ITRequest?.Client?.Title===client &&
x.License?.Title===license &&
(
typeof x.Status==="string"
? x.Status
: x.Status?.Value
)!=="Released"
).length;

}

public render(){

if(this.state.loading)
return <div className={styles.loading}>Loading licenses...</div>;

if(this.state.error)
return <div className={styles.error}>{this.state.error}</div>;

return <div className={styles.page}>

<div className={styles.header}>
<h2>License Allocation Matrix</h2>

<button
className={styles.backButton}
onClick={this.props.onBack}
>
← Dashboard
</button>

</div>

<table>
<thead>
<tr>
<th>Client</th>
{this.state.licenses.map(l=><th key={l}>{l}</th>)}
</tr>
</thead>

<tbody>

{this.state.clients.map(client=>

<tr
key={client}
onClick={()=>this.props.onClientSelect?.(client)}
className={styles.row}
>

<td>{client}</td>

{this.state.licenses.map(l=>

<td key={l}>
{this.getCount(client,l)}
</td>

)}

</tr>

)}

</tbody>

</table>

{this.state.clients.length===0 &&
<div className={styles.empty}>
No license allocations found
</div>
}

</div>;

}

}
